/* No automatic essay transmission. Each model request requires an explicit consent and send action. */
let essayRequestController=null,essayRequestTarget=null;
async function readApplicationAttachment(file,maxCharacters){if(/\.pdf$/i.test(file.name)){if(file.size>5*1024*1024)throw Error('Use a PDF of up to 5 MB.');const bytes=new Uint8Array(await file.arrayBuffer());if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-')throw Error('That file is not a PDF.');await loadDocLibraries();const pdf=await pdfjsLib.getDocument({data:bytes,isEvalSupported:false,standardFontDataUrl:new URL('vendor/standard_fonts/',document.baseURI).href}).promise;let text='';try{if(pdf.numPages>10)throw Error('Use a PDF of up to 10 pages.');for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);text+=TranscriptImport.pdfText((await page.getTextContent()).items)+'\n\n';if(text.length>maxCharacters)throw Error('The document is too long for this field.')}}finally{await pdf.destroy()}if(!text.trim())throw Error('This PDF has no extractable text. Paste its text or use a text-based PDF.');return text}if(!/\.txt$/i.test(file.name)||file.size>100*1024)throw Error('Use a TXT file up to 100 KB or a text PDF up to 5 MB.');const text=await file.text();if(text.length>maxCharacters||/[\u0000-\u0008\u000e-\u001f]/.test(text))throw Error('Use a plain-text document within the field length limit.');return text}
function substantiveReviewTools(){return `<details class="journey-advanced" id="substantive-review"><summary>Get a detailed AI writing review</summary><p>Review prompt coverage, concrete examples, impact and reflection. Receive evidence-based encouragement and specific revisions. This is writing feedback, not an admission prediction or a replacement for a counselor.</p><p>When you choose Send for review, your current statement, prompt and activities are sent to Cloudflare Workers AI. Completed coursework is included only if you opt in. Camino does not persist the request on its server; Cloudflare's processing and privacy terms apply. Remove names, IDs and other details you do not need reviewed.</p><label><input id="review-coursework-consent" type="checkbox"> Include up to 40 completed course codes, titles and grades for context.</label><label><input id="review-send-consent" type="checkbox"> I agree to send this draft, prompt and activities to Cloudflare Workers AI for this review.</label><div class="actions"><button class="btn primary" id="send-ai-review">Send for review ↗</button><button class="btn" id="cancel-ai-review" disabled>Cancel</button></div><p id="ai-review-availability" class="quiet-note">The service is checked only when you request a review. Local writing checks work without AI.</p><section id="ai-review-result" aria-live="polite"></section><details><summary>Informatics: writing and AI-use policy</summary><p>The official application page currently publishes three 250-word sections for Winter 2027. Verify your own cycle’s prompts. It allows limited grammar/phrasing assistance, prohibits generating and submitting an essay from prompts or notes, and asks how AI tools were used. Keep your own experiences and voice; this tool gives revision suggestions and does not write a replacement essay.</p><a class="journey-secondary" href="${AcademicEvidence.info.essay.source}" target="_blank" rel="noopener">Official prompts and AI-use policy ↗</a></details></details>`}
function showModelReview(review){return `<span class="eyebrow">REVIEW OF YOUR SUBMITTED DRAFT · VERIFY AI SUGGESTIONS</span><h3>${esc(review.summary||'Your draft review')}</h3>${[['strengths','What is working'],['improvements','What to revise next'],['promptCoverage','Prompt coverage']].map(([key,title])=>`<h3>${title}</h3>${(review[key]||[]).map(item=>`<article class="degree-goal">${item.evidence?`<blockquote>${esc(item.evidence)}</blockquote>`:''}<p>${esc(item.feedback)}</p>${item.action?`<p><strong>Try this:</strong> ${esc(item.action)}</p>`:''}${key==='improvements'?`<span class="eyebrow">${esc(item.priority)} revision priority</span>`:''}</article>`).join('')||'<p>No specific feedback returned for this section.</p>'}`).join('')}<p class="quiet-note">${esc(review.limitations)} A reviewer may miss strengths or problems. No admissions score or percentage is calculated.</p>`}
function bindAIReview(){const button=document.querySelector('#send-ai-review');if(!button)return;const form=document.querySelector('#essay-review'),result=document.querySelector('#ai-review-result'),cancel=document.querySelector('#cancel-ai-review');for(const [id,name,max]of [['essay-file','essay',30000],['activities-file','activities',15000]]){const input=document.getElementById(id);if(input)input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{const text=await readApplicationAttachment(file,max);if(form.isConnected&&input.files?.[0]===file){form.elements.namedItem(name).value=text;toast('Document loaded locally. Nothing has been sent for AI review.')}}catch(error){if(form.isConnected)toast(error.message)}}}form.addEventListener('input',()=>{if(essayRequestController){essayRequestController.abort();result.textContent='Draft changed. The previous review request was cancelled; send the new version when ready.'}});document.querySelector('#clear-application-draft')?.addEventListener('click',()=>{essayRequestController?.abort();result.textContent='';document.querySelector('#review-send-consent').checked=false});cancel.onclick=()=>{essayRequestController?.abort();result.textContent='Review cancelled. A request already received by the provider may still finish; Camino will ignore its result.'};button.onclick=async()=>{if(essayRequestController)return;if(!document.querySelector('#review-send-consent').checked)return toast('Check the consent box before sending your draft.');const f=Object.fromEntries(new FormData(form));if(!f.prompt.trim()||f.essay.trim().length<60)return toast('Add the exact prompt and a draft of at least 60 characters.');const coursework=document.querySelector('#review-coursework-consent').checked?state.courses.filter(E.passing).slice(0,40).map(c=>({code:c.code,title:c.title,grade:c.grade})):[];const payload={prompt:f.prompt,essay:f.essay,activities:f.activities,wordLimit:f.limit?Number(f.limit):null,coursework,consent:true};if(new TextEncoder().encode(JSON.stringify(payload)).byteLength>70000)return toast('This review is too large. Shorten the draft or activities and try again.');const controller=new AbortController();essayRequestController=controller;essayRequestTarget=result;button.disabled=true;cancel.disabled=false;result.innerHTML='<p role="status">Reading your draft and preparing revision suggestions…</p>';try{const response=await fetch('/api/application-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:controller.signal});const data=await response.json();if(!result.isConnected||controller.signal.aborted)return;if(!response.ok)throw Error(data.error||'The review service is unavailable on this deployment.');if(!data.review)throw Error('The service did not return a review.');result.innerHTML=showModelReview(data.review)}catch(error){if(result.isConnected&&!controller.signal.aborted)result.innerHTML=`<p role="alert">${esc(error.message||'Could not complete the review.')} Your local draft is preserved.</p>`}finally{if(essayRequestController===controller){essayRequestController=null;essayRequestTarget=null}if(button.isConnected)button.disabled=false;if(cancel.isConnected)cancel.disabled=true}}}
function installAIReview(){const beforePage=advisingPage;advisingPage=()=>beforePage().replace('<label>Extracurriculars, work, care responsibilities or projects', '<label>Load activities or a résumé (TXT or text PDF)<input id="activities-file" type="file" accept=".txt,.pdf,text/plain,application/pdf"></label><label>Extracurriculars, work, care responsibilities or projects').replace('<div id="essay-feedback" aria-live="polite"></div>','<div id="essay-feedback" aria-live="polite"></div>'+substantiveReviewTools()).replace('No external AI service is connected. Saved essay text','Local checks never send text. The optional detailed review sends only after consent. Saved essay text');const beforeBind=bind;bind=()=>{beforeBind();if(essayRequestController&&!essayRequestTarget?.isConnected){essayRequestController.abort();essayRequestController=null;essayRequestTarget=null}bindAIReview()}}
